/**
 * Central map of every brand asset used by the UI.
 * Files are generated by scripts/process-assets.py from design-source/originals;
 * intrinsic sizes come from the generated manifest so images never distort.
 */
import manifest from "./asset-manifest.json";

export type Asset = { src: string; width: number; height: number };
const m = manifest as Record<string, Asset>;

export const brand = {
  logo: m.logo,
} as const;

export type CharacterId = "jamool" | "thaloob" | "zizou" | "noor" | "maha";

export const characterImages: Record<CharacterId, Asset> = {
  jamool: m.jamool,
  thaloob: m.thaloob,
  zizou: m.zizou,
  noor: m.noor,
  maha: m.maha,
};

export const characterAlternates = {
  jamoolAlt: m.jamoolAlt,
  zizouStar: m.zizouStar,
} as const;

export type SectionId =
  | "stories"
  | "learn"
  | "surahs"
  | "games"
  | "art"
  | "ai"
  | "values"
  | "competitions";

/**
 * Section icons. The supplied `ai.png` was a byte-identical copy of
 * `stories.png`, so the AI section temporarily uses Zizou's own artwork
 * until an approved icon is delivered (see docs/asset-inventory.md).
 */
export const sectionIcons: Record<SectionId, Asset & { provisional?: boolean }> = {
  stories: m.storiesIcon,
  learn: m.learnIcon,
  surahs: m.surahsIcon,
  games: m.gamesIcon,
  art: m.artIcon,
  ai: { ...m.zizouStar, provisional: true },
  values: m.valuesIcon,
  competitions: m.competitionsIcon,
};

export const illustrations = {
  friendsGroup: m.friendsGroup,
  friendsLineup: m.friendsLineup,
  oasisScene: m.oasisScene,
  mediaIcon: m.mediaIcon,
} as const;
